const request = $input.first().json;
const headers = request.headers || {};
const body = request.body || request;
const providedSecret = String(headers['x-buma-secret'] || '');
const expectedSecret = String($env.N8N_SHARED_SECRET || '');
const required = ['order_id','action','sender_email','subject','draft_reply','decision','status'];
const missing = required.filter((key) => !String(body[key] ?? '').trim());
let valid = true;
let http_status = 200;
let error = '';
if (!expectedSecret || providedSecret !== expectedSecret) { valid = false; http_status = 403; error = 'Invalid shared secret'; }
else if (missing.length) { valid = false; http_status = 400; error = `Missing fields: ${missing.join(', ')}`; }
else if (body.action !== 'approve') { valid = false; http_status = 400; error = 'Unsupported action'; }
else if (body.decision === 'manual_required') { valid = false; http_status = 409; error = 'manual_required cannot be sent automatically'; }
const idempotency_key = String(headers['x-idempotency-key'] || body.idempotency_key || '').trim();
if (valid && !idempotency_key) { valid = false; http_status = 400; error = 'Missing idempotency key'; }
const store = $getWorkflowStaticData('global');
store.approveKeys = store.approveKeys || {};
const duplicate = valid && Boolean(store.approveKeys[idempotency_key]);
if (valid && !duplicate) store.approveKeys[idempotency_key] = { status: 'pending', created_at: new Date().toISOString() };
return [{ json: { ...body, valid, http_status, error, idempotency_key, duplicate, test_mode: body.test_mode === true } }];

const item = $input.first().json;
const store = $getWorkflowStaticData('global');
store.approveKeys[item.idempotency_key] = { status: 'dry_run', created_at: new Date().toISOString() };
return [{ json: { success: true, status: 'accepted', test_mode: true, email_sent: false, idempotency_key: item.idempotency_key } }];

const request = $('Validate secret and idempotency').first().json;
const gmail = $input.first().json;
const message_id = String(gmail.id || gmail.messageId || gmail.message_id || '');
const sent_at = new Date().toISOString();
const store = $getWorkflowStaticData('global');
store.approveKeys[request.idempotency_key] = { status: 'sent', sent_at, message_id };
return [{ json: { success: true, status: 'sent', email_sent: true, sent_at, message_id, idempotency_key: request.idempotency_key } }];

const request = $('Validate secret and idempotency').first().json;
const failure = $input.first().json;
const send_error = String(failure.error?.message || failure.message || failure.error || 'Gmail send failed').slice(0, 2000);
const store = $getWorkflowStaticData('global');
store.approveKeys[request.idempotency_key] = { status: 'send_error', send_error, failed_at: new Date().toISOString() };
return [{ json: { success: false, status: 'send_error', email_sent: false, send_error, idempotency_key: request.idempotency_key } }];
